const body = $input.first().json.body;
const timestamp = body.timestamp || new Date().toISOString();
const fileName = (body.storagePath || '').split('/').pop() || body.title || 'plik.pdf';
const wMode = String(body.workflowMode || '').toLowerCase();
const tCol = String(body.targetCollection || body.collection || '').toLowerCase();
const bType = String(body.type || '').toLowerCase();
const shouldCreateTasks = String(body.shouldCreateTasks || '').toLowerCase();
// Tryb lesson tylko jesli jawnie wskazany
const isLesson = (wMode === 'lesson' || tCol === 'lessons' || bType === 'lesson') && shouldCreateTasks !== 'false';
const mode = isLesson ? 'lesson' : 'material';
const docId = mode === 'lesson' ? 'lesson_pdf_' + Date.now() : 'material_pdf_' + Date.now();
return [{ json: {
  docId, mode,
  teacherId: body.teacherId || '',
  classId: body.classId || '',
  className: body.className || '',
  subject: body.classSubject || body.subject || '',
  title: body.title || fileName,
  pdfUrl: body.pdfUrl || '',
  storagePath: body.storagePath || '',
  fileName, timestamp,
  hasPdfUrl: !!(body.pdfUrl && body.pdfUrl.trim())
}}];

