const item = $input.first().json;
let rawText = '';
if (item.output && Array.isArray(item.output) && item.output[0] && item.output[0].content) {
  const ct = item.output[0].content[0] && item.output[0].content[0].text;
  rawText = (typeof ct === 'object' && ct !== null) ? JSON.stringify(ct) : String(ct || '');
}
if (!rawText && typeof item.output === 'string') { rawText = item.output; }
if (!rawText && item.text) { rawText = String(item.text); }
rawText = rawText.trim();
const tick3 = String.fromCharCode(96,96,96);
if (rawText.startsWith(tick3)) {
  const nl = rawText.indexOf(10); rawText = rawText.slice(nl + 1);
  const lt = rawText.lastIndexOf(tick3); if (lt !== -1) rawText = rawText.slice(0, lt);
  rawText = rawText.trim();
}
let parsed = null;
try { parsed = JSON.parse(rawText); } catch(e) {}
if (!parsed) {
  const s = rawText.indexOf('{'); const e2 = rawText.lastIndexOf('}');
  if (s !== -1 && e2 !== -1) { try { parsed = JSON.parse(rawText.substring(s, e2+1)); } catch(e) {} }
}
if (!parsed) { parsed = { title: '', summary: '', note: rawText, quiz: [] }; }
const meta = $('Przygotuj Metadane i Tryb').first().json;
const quiz = Array.isArray(parsed.quiz) ? parsed.quiz.filter(function(q) { return typeof q === 'string' && q.trim(); }) : [];
const firestoreBody = JSON.stringify({ fields: {
  lessonId: { stringValue: meta.docId },
  classId: { stringValue: meta.classId },
  teacherId: { stringValue: meta.teacherId },
  title: { stringValue: String(parsed.title || meta.title) },
  summary: { stringValue: String(parsed.summary || '') },
  note: { stringValue: String(parsed.note || '') },
  transcript: { stringValue: '' },
  source: { stringValue: 'pdf_lesson' },
  type: { stringValue: 'lesson' },
  status: { stringValue: 'done' },
  processingStatus: { stringValue: 'done' },
  pdfUrl: { stringValue: meta.pdfUrl },
  storagePath: { stringValue: meta.storagePath },
  fileName: { stringValue: meta.fileName },
  timestamp: { stringValue: meta.timestamp },
  createdAt: { stringValue: meta.timestamp }
}});
return [{ json: { ...meta, title: parsed.title || meta.title, summary: parsed.summary || '', note: parsed.note || '', quiz, firestoreBody } }];

const classDoc = $input.first().json;
const studentIds = classDoc.fields?.studentIds?.arrayValue?.values?.map(function(v) { return v.stringValue; }) || [];
const lessonData = $('Parsuj Lekcję GPT').first().json;
const questionsValues = lessonData.quiz.map(function(q) { return { stringValue: q }; });
return studentIds.map(function(studentId) {
  const taskId = 'task_' + studentId + '_' + lessonData.docId;
  const firestoreBody = JSON.stringify({ fields: {
    taskId: { stringValue: taskId },
    lessonId: { stringValue: lessonData.docId },
    studentId: { stringValue: studentId },
    classId: { stringValue: lessonData.classId },
    teacherId: { stringValue: lessonData.teacherId },
    questions: { arrayValue: { values: questionsValues } },
    answeredCount: { integerValue: '0' },
    status: { stringValue: 'locked' },
    quizStatus: { stringValue: 'required' },
    noteUnlocked: { booleanValue: false },
    exercisesUnlocked: { booleanValue: false },
    createdAt: { stringValue: lessonData.timestamp }
  }});
  return { json: { taskId, studentId, firestoreBody, lessonId: lessonData.docId } };
});

