  if (s !== -1 && e2 !== -1) { try { parsed = JSON.parse(rawText.substring(s, e2+1)); } catch(e) {} }
}
if (!parsed) { parsed = { title: '', shortTitle: '', description: '', keyPoints: [], sections: [], importantTerms: [], recapQuestions: [], note: rawText }; }

const meta = $('Przygotuj Metadane i Tryb').first().json;
const title = String(parsed.title || meta.title);
const shortTitle = String(parsed.shortTitle || title);
const description = String(parsed.description || '');
const note = String(parsed.note || '');
