const importantTerms = Array.isArray(parsed.importantTerms) ? parsed.importantTerms : [];
const recapQuestions = Array.isArray(parsed.recapQuestions) ? parsed.recapQuestions : [];

// Konwertuj tablice obiektow do Firestore arrayValue
const toStrArr = function(arr) { return { arrayValue: { values: arr.map(function(s) { return { stringValue: String(s) }; }) } }; };
const toJsonArr = function(arr) { return { arrayValue: { values: arr.map(function(o) { return { stringValue: JSON.stringify(o) }; }) } }; };

const firestoreBody = JSON.stringify({ fields: {
  materialId: { stringValue: meta.docId },
  classId: { stringValue: meta.classId },
  teacherId: { stringValue: meta.teacherId },
  title: { stringValue: title },
  shortTitle: { stringValue: shortTitle },
  description: { stringValue: description },
  keyPoints: toStrArr(keyPoints),
  sections: toJsonArr(sections),
  importantTerms: toJsonArr(importantTerms),
  recapQuestions: toJsonArr(recapQuestions),
  note: { stringValue: note },
  pdfUrl: { stringValue: meta.pdfUrl },
  storagePath: { stringValue: meta.storagePath },
  fileName: { stringValue: meta.fileName },
  source: { stringValue: 'pdf_material' },
  type: { stringValue: 'additional_material' },
  category: { stringValue: 'additional_materials' },
  processingStatus: { stringValue: 'done' },
  status: { stringValue: 'done' },
  timestamp: { stringValue: meta.timestamp },
  createdAt: { stringValue: meta.timestamp }
}});

return [{ json: { ...meta, title, shortTitle, description, note, firestoreBody } }];
